@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap');
:root{--bg:#10110f;--panel:#181a17;--panel2:#20221e;--line:#30332d;--text:#f2f0e9;--muted:#9a9d93;--lime:#d8f36a;--orange:#ff875d;--blue:#8eb8ff;--green:#8cd6a2;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',Arial,sans-serif;--mono:'DM Mono',monospace}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);min-height:100vh}button,input,select{font:inherit}button{cursor:pointer;color:inherit}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--lime);outline-offset:2px}.app-shell{display:grid;grid-template-columns:230px minmax(0,1fr);min-height:100vh}.sidebar{border-right:1px solid var(--line);padding:24px 14px;display:flex;flex-direction:column;gap:24px;position:sticky;top:0;height:100vh;background:#131411;z-index:5}.brand{font-family:var(--serif);font-size:27px;font-weight:800;letter-spacing:.14em;padding:0 12px}.brand span{color:var(--lime)}.brand small{display:block;color:var(--muted);font:10px var(--mono);letter-spacing:.12em;margin-top:3px}.side-nav{display:grid;gap:5px}.nav-label{color:#72766e;font:10px var(--mono);letter-spacing:.15em;padding:13px 12px 5px}.nav-btn{background:transparent;border:0;text-align:left;color:#a8aaa2;padding:11px 12px;border-radius:8px;display:flex;align-items:center;gap:11px;font-size:13px;transition:.18s}.nav-btn:hover,.nav-btn.active{background:#272a23;color:var(--text)}.nav-btn.active{box-shadow:inset 2px 0 var(--lime);color:var(--lime)}.nav-icon{font-size:16px;width:19px;text-align:center}.side-bottom{margin-top:auto;border-top:1px solid var(--line);padding:15px 10px 0;color:var(--muted);font:11px var(--mono)}.main{min-width:0;padding:27px clamp(18px,4vw,56px) 90px;max-width:1600px;margin:0 auto;width:100%}.topbar{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:28px}.eyebrow{font:10px var(--mono);text-transform:uppercase;letter-spacing:.16em;color:var(--muted)}.top-actions{display:flex;align-items:center;gap:10px}.stat-pill{border:1px solid var(--line);border-radius:8px;padding:8px 11px;font:11px var(--mono);color:#c8cabf}.stat-pill b{color:var(--lime);font-weight:500}.btn{border:1px solid var(--line);background:#242720;border-radius:7px;padding:10px 14px;color:var(--text);font-size:12px;font-weight:600;transition:.18s}.btn:hover{border-color:#74796c;transform:translateY(-1px)}.btn.primary{background:var(--lime);border-color:var(--lime);color:#151710}.btn.danger{color:#ff9a82}.btn.ghost{background:transparent}.btn.small{padding:7px 10px;font-size:11px}.btn:disabled{opacity:.42;cursor:not-allowed;transform:none}.page-title{font:700 clamp(28px,4vw,43px) var(--serif);letter-spacing:-.03em;margin:0 0 7px}.page-subtitle{color:var(--muted);margin:0 0 25px;font-size:13px;line-height:1.55}.hero{background:linear-gradient(115deg,#242920,#191b17 58%,#242319);border:1px solid #383b30;border-radius:12px;padding:25px;position:relative;overflow:hidden;margin-bottom:17px}.hero:after{content:'✦';position:absolute;right:5%;top:-55px;font-size:240px;color:rgba(216,243,106,.055);font-family:var(--serif)}.hero-content{display:grid;grid-template-columns:130px 1fr;gap:25px;align-items:center;position:relative;z-index:1}.avatar{width:125px;height:145px;border-radius:7px;background:linear-gradient(150deg,#776d51,#302c25 60%,#171915);display:grid;place-items:center;font-size:60px;border:1px solid #565746;position:relative}.avatar:after{content:'ARTIST PORTRAIT';position:absolute;bottom:8px;font:8px var(--mono);letter-spacing:.14em;color:#d0ccba}.hero-name{font:700 clamp(28px,4vw,42px) var(--serif);margin:4px 0}.artist-handle{font:12px var(--mono);color:var(--lime);letter-spacing:.08em}.hero-meta{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 18px}.tag{border:1px solid #45483d;border-radius:99px;color:#c4c6bb;padding:5px 9px;font:10px var(--mono)}.hero-actions{display:flex;gap:8px;flex-wrap:wrap}.metric-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-bottom:18px}.metric{background:var(--panel);border:1px solid var(--line);padding:13px 15px;border-radius:8px}.metric-label{color:var(--muted);font:9px var(--mono);letter-spacing:.12em;text-transform:uppercase}.metric-value{font:700 23px var(--serif);margin-top:7px}.metric-note{font-size:10px;color:var(--muted);margin-top:3px}.metric.heat .metric-value{color:var(--orange)}.metric.cash .metric-value{color:var(--lime)}.columns{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(260px,.8fr);gap:15px}.card{background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:19px;margin-bottom:15px;min-width:0}.card-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:15px}.card-title{font:700 17px var(--serif);margin:0}.card-kicker{font:9px var(--mono);color:var(--muted);letter-spacing:.14em;text-transform:uppercase}.release-row,.list-row{display:flex;align-items:center;gap:12px;padding:11px 0;border-top:1px solid #2a2c27}.release-row:first-of-type,.list-row:first-of-type{border-top:0}.cover{width:43px;height:43px;background:#32372a;border-radius:5px;display:grid;place-items:center;color:var(--lime);font-size:18px;flex:none}.row-main{min-width:0;flex:1}.row-title{font-size:13px;font-weight:600}.row-sub{font-size:10px;color:var(--muted);margin-top:4px}.row-value{text-align:right;font:11px var(--mono);color:#d7d8cf}.feed{display:grid;gap:0}.feed-item{display:flex;gap:10px;padding:11px 0;border-top:1px solid #2a2c27}.feed-item:first-child{border-top:0;padding-top:0}.feed-icon{width:26px;height:26px;border-radius:50%;background:#2b2e25;display:grid;place-items:center;flex:none;font-size:12px}.feed-text{font-size:11px;line-height:1.5;color:#dadbd3}.feed-time{font:9px var(--mono);color:#777a71;margin-top:4px}.empty{padding:25px 10px;text-align:center;color:var(--muted);font-size:12px;border:1px dashed #3b3e36;border-radius:7px;line-height:1.6}.quick-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.quick-card{background:#20221e;border:1px solid var(--line);border-radius:7px;padding:14px;text-align:left;transition:.18s}.quick-card:hover{border-color:#777c67;transform:translateY(-2px)}.quick-card b{display:block;font:15px var(--serif);margin:8px 0 4px}.quick-card span{font-size:10px;color:var(--muted);line-height:1.45}.quick-icon{font-size:20px}.section-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field{display:grid;gap:6px;margin-bottom:12px}.field label{font:10px var(--mono);letter-spacing:.08em;text-transform:uppercase;color:#b9bbb2}.field input,.field select{background:#11120f;border:1px solid #393c34;color:var(--text);border-radius:6px;padding:10px 11px;width:100%;font-size:12px}.field input::placeholder{color:#65695f}.field .help{font-size:10px;color:var(--muted)}.table{width:100%;border-collapse:collapse;font-size:11px}.table th{text-align:left;color:#85897f;font:9px var(--mono);letter-spacing:.12em;text-transform:uppercase;padding:10px 8px;border-bottom:1px solid var(--line)}.table td{padding:11px 8px;border-bottom:1px solid #292b26;color:#dedfd6}.rank{color:var(--lime);font:13px var(--mono);width:35px}.up{color:var(--green)}.down{color:var(--orange)}.bar{height:5px;background:#2c2e28;border-radius:9px;overflow:hidden;margin-top:8px}.bar i{display:block;height:100%;background:var(--lime);border-radius:9px}.tabs{display:flex;gap:7px;overflow:auto;margin:15px 0;border-bottom:1px solid var(--line)}.tab{background:none;border:0;color:var(--muted);white-space:nowrap;padding:9px 10px 11px;font-size:11px;border-bottom:2px solid transparent}.tab.active{color:var(--lime);border-color:var(--lime)}.badge{display:inline-block;padding:4px 7px;background:#292d22;border-radius:4px;color:var(--lime);font:9px var(--mono);letter-spacing:.06em}.badge.orange{color:#ffae91;background:#38271f}.badge.blue{color:#a7c7ff;background:#222b37}.badge.gray{color:#b4b6ad;background:#2a2b27}.split{display:flex;align-items:center;justify-content:space-between;gap:12px}.progress{font:10px var(--mono);color:var(--muted)}.news-feed{max-height:360px;overflow:auto}.wealth-row{display:flex;justify-content:space-between;font-size:11px;padding:9px 0;border-bottom:1px solid #2b2d27}.wealth-row span:last-child{font-family:var(--mono)}.wealth-total{font:700 25px var(--serif);color:var(--lime)}.modal-backdrop{position:fixed;inset:0;background:rgba(5,6,5,.78);display:grid;place-items:center;padding:17px;z-index:20;backdrop-filter:blur(5px)}.modal{width:min(600px,100%);max-height:min(90vh,850px);overflow:auto;background:#1a1c18;border:1px solid #45483d;border-radius:11px;padding:23px;box-shadow:0 25px 80px #0009}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:17px}.modal-title{font:700 25px var(--serif);margin:0}.modal-close{border:0;background:none;color:var(--muted);font-size:22px}.modal-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:15px;padding-top:14px;border-top:1px solid var(--line)}.modal-buttons{display:flex;gap:8px;justify-content:flex-end}.notice{border-left:2px solid var(--lime);background:#24271f;padding:11px 13px;color:#bdc0b5;font-size:11px;line-height:1.5;margin:12px 0}.choice-list{display:grid;gap:8px}.choice{width:100%;text-align:left;background:#22241f;border:1px solid #3c4035;padding:12px;border-radius:6px}.choice:hover{border-color:var(--lime)}.choice b{font-size:12px}.choice span{display:block;color:var(--muted);font-size:10px;margin-top:4px;line-height:1.45}.slot-list{display:grid;gap:9px}.slot{background:#22241f;border:1px solid var(--line);padding:14px;border-radius:7px;display:flex;justify-content:space-between;gap:15px;align-items:center}.slot-info b{font:16px var(--serif)}.slot-info span{display:block;color:var(--muted);font:10px var(--mono);margin-top:6px}.report-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.report-stat{background:#22241f;border-radius:6px;padding:11px}.report-stat span{display:block;font:9px var(--mono);color:var(--muted);text-transform:uppercase;letter-spacing:.1em}.report-stat b{display:block;margin-top:6px;font:17px var(--serif)}.mobile-bar{display:none}.creation-screen{min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(ellipse at 30% 20%,#2a2b21 0%,transparent 45%),var(--bg)}.creation-card{width:min(760px,100%);background:#181a17;border:1px solid #383b31;border-radius:12px;padding:clamp(22px,5vw,45px)}.creation-logo{font:800 12px var(--mono);letter-spacing:.25em;color:var(--lime)}.creation-title{font:700 clamp(37px,7vw,64px) var(--serif);line-height:1.02;max-width:600px;margin:18px 0}.creation-copy{font-size:13px;color:var(--muted);line-height:1.6;max-width:550px;margin-bottom:25px}.creation-form{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.creation-form .field.wide{grid-column:1/-1}.decade-list{display:flex;gap:7px;flex-wrap:wrap}.decade-chip{border:1px solid var(--line);background:#20221e;border-radius:99px;padding:8px 12px;color:#b8bbb0;font:10px var(--mono)}.decade-chip.selected{background:#343a23;border-color:var(--lime);color:var(--lime)}.setting-row{padding:12px 0;border-bottom:1px solid #2a2c27;display:flex;justify-content:space-between;align-items:center;gap:15px;font-size:12px}.toggle{appearance:none;width:36px;height:20px;border-radius:99px;background:#4a4b45;position:relative;cursor:pointer}.toggle:checked{background:#9cb348}.toggle:after{content:'';position:absolute;width:14px;height:14px;left:3px;top:3px;border-radius:50%;background:white;transition:.18s}.toggle:checked:after{left:19px}.toast{margin:0 0 8px;background:#272a24;border:1px solid #464a3a;padding:12px 16px;border-radius:7px;box-shadow:0 8px 35px #0008;font-size:12px;animation:toastin .2s ease}.toast-root{position:fixed;right:20px;bottom:20px;z-index:50;display:grid}.toast-root:not(:empty){position:fixed;right:20px;bottom:20px;z-index:50;display:grid}@keyframes toastin{from{transform:translateY(8px);opacity:0}to{transform:none;opacity:1}}.achievement{display:flex;gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid #2b2d27}.achievement .medal{font-size:19px}.achievement b{display:block;font-size:11px}.achievement span{color:var(--muted);font-size:10px}.portrait-picker{display:flex;gap:8px;flex-wrap:wrap}.portrait-option{font-size:23px;width:42px;height:42px;background:#252720;border:1px solid var(--line);border-radius:5px}.portrait-option.selected{border-color:var(--lime);background:#363b28}.tiny{font-size:10px;color:var(--muted);line-height:1.5}.footer-note{font:9px var(--mono);color:#74786d;padding-top:10px}
@media(max-width:900px){.app-shell{grid-template-columns:68px minmax(0,1fr)}.sidebar{padding:20px 8px;align-items:center}.brand{padding:0;font-size:18px}.brand small,.nav-label,.nav-btn .nav-text,.side-bottom{display:none}.side-nav{width:100%}.nav-btn{justify-content:center;padding:12px 0}.nav-icon{width:auto}.main{padding:20px clamp(13px,3vw,30px) 90px}.topbar{margin-bottom:20px}.stat-pill{padding:7px 8px;font-size:9px}.metric-grid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:620px){.app-shell{display:block}.sidebar{display:none}.main{padding:17px 14px 90px}.topbar{align-items:flex-start}.topbar .eyebrow{max-width:120px;line-height:1.5}.top-actions{gap:5px;flex-wrap:wrap;justify-content:flex-end}.stat-pill{font-size:8px;padding:6px}.top-actions .btn{font-size:10px;padding:8px}.hero{padding:16px}.hero-content{grid-template-columns:82px 1fr;gap:14px}.avatar{width:82px;height:105px;font-size:42px}.hero-name{font-size:27px}.hero-meta{margin:8px 0 12px}.metric-grid{grid-template-columns:repeat(2,1fr);gap:7px}.metric{padding:10px}.metric-value{font-size:20px}.columns,.section-grid{grid-template-columns:1fr;gap:0}.quick-grid{grid-template-columns:repeat(2,1fr)}.creation-form,.form-grid{grid-template-columns:1fr}.creation-form .field.wide{grid-column:auto}.creation-card{padding:24px 18px}.table{font-size:10px}.table th{font-size:8px;padding:8px 4px}.table td{padding:9px 4px}.mobile-bar{display:flex;position:fixed;bottom:0;left:0;right:0;z-index:8;background:#171815f5;border-top:1px solid var(--line);padding:7px max(5px,env(safe-area-inset-right)) calc(7px + env(safe-area-inset-bottom)) max(5px,env(safe-area-inset-left));justify-content:space-around;backdrop-filter:blur(8px)}.mobile-bar button{border:0;background:transparent;color:var(--muted);font-size:8px;display:grid;justify-items:center;gap:3px;min-width:42px}.mobile-bar button.active{color:var(--lime)}.mobile-bar i{font-style:normal;font-size:16px}.report-grid{grid-template-columns:1fr 1fr}.modal{padding:18px}.slot{align-items:flex-start;flex-direction:column}.slot .modal-buttons{align-self:flex-end}.page-title{font-size:32px}}

/* GOLDEN — Music Industry Life Sim, version 1. Slot-scoped local saves. */
(()=>{'use strict';
const KEY='golden-saves-v1',SETTINGS='golden-settings-v1';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n||0),compact=n=>new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(n||0),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),pick=a=>a[Math.floor(Math.random()*a.length)],id=()=>Math.random().toString(36).slice(2,9);
const eras=[
{from:1970,to:1979,tag:'THE SOUL & DISCO ERA',genres:['Soul','Funk','Disco','Jazz','Gospel','Rock'],tech:'8-track tape · FM radio · vinyl',dist:'Vinyl & radio'},
{from:1980,to:1989,tag:'THE MTV & SYNTH ERA',genres:['R&B','Soul','New Jack Swing','Hip-Hop','Funk','Pop','Rock'],tech:'Cassette · drum machines · music video',dist:'Vinyl, cassette & video'},
{from:1990,to:1999,tag:'THE CD & HIP-HOP ERA',genres:['R&B','Hip-Hop','Rap','Neo-Soul','Pop','Rock','Jazz'],tech:'CD · samplers · home studios',dist:'CD, cassette & radio'},
{from:2000,to:2009,tag:'THE DIGITAL DOWNLOAD ERA',genres:['Contemporary R&B','Hip-Hop','Rap','Pop','Neo-Soul','Alternative R&B'],tech:'Pro Tools · MP3 · online stores',dist:'CD, downloads & ringtones'},
{from:2010,to:2019,tag:'THE STREAMING ERA',genres:['Contemporary R&B','Alternative R&B','Hip-Hop','Rap','Pop','Neo-Soul','Gospel'],tech:'DAWs · streaming · social media',dist:'Downloads & streaming'},
{from:2020,to:2029,tag:'THE CREATOR ECONOMY',genres:['Contemporary R&B','Alternative R&B','Hip-Hop','Rap','Pop','Neo-Soul','Jazz'],tech:'Remote studios · short-form video · AI tools',dist:'Streaming & direct-to-fan'},
{from:2030,to:9999,tag:'THE NEXT SOUND',genres:['Contemporary R&B','Alternative R&B','Hip-Hop','Rap','Pop','Neo-Soul'],tech:'Immersive audio · direct-to-fan',dist:'Global digital platforms'}];
const era=y=>eras.find(e=>y>=e.from&&y<=e.to)||eras[eras.length-1];
const famous=[['Stevie Wonder','Soul',1950,2020],['Marvin Gaye','Soul',1939,1984],['Aretha Franklin','Soul',1942,2018],['Donna Summer','Disco',1948,2012],['Diana Ross','Soul',1944,2026],['Prince','Funk',1958,2016],['Whitney Houston','R&B',1963,2012],['Janet Jackson','R&B',1966,2026],['Michael Jackson','Pop',1958,2009],['Tina Turner','Rock',1939,2023],['Bobby Brown','New Jack Swing',1969,2026],['Teddy Riley','New Jack Swing',1967,2026],['Mary J. Blige','R&B',1971,2026],['TLC','R&B',1970,2026],['Aaliyah','R&B',1979,2001],['Lauryn Hill','Hip-Hop',1975,2026],['Nas','Hip-Hop',1973,2026],['Jay-Z','Hip-Hop',1969,2026],['Missy Elliott','Hip-Hop',1971,2026],['Beyoncé','R&B',1981,2026],['Usher','R&B',1978,2026],['Alicia Keys','R&B',1981,2026],['Kanye West','Hip-Hop',1977,2026],['Rihanna','Pop',1988,2026],['Drake','Hip-Hop',1986,2026],['Frank Ocean','Alternative R&B',1987,2026],['SZA','R&B',1989,2026],['The Weeknd','R&B',1990,2026],['Kendrick Lamar','Hip-Hop',1987,2026],['Tyler, the Creator','Hip-Hop',1991,2026],['H.E.R.','R&B',1997,2026],['Victoria Monét','R&B',1989,2026]];
const firsts=['Jade','Marcus','Nova','Darius','Imani','Theo','Avery','Renee','Malik','Sage','Zion','Nia','Cruz','Ari','Milan','Amara','Kai','Raven','Andre','Skye','Jules','Khalil','Lena','Noel'];
const lasts=['Stone','Monroe','Banks','Carter','Reed','Wilder','James','Cole','Brooks','Saint','Mercer','Blue','Knight','Ellis','Cruz','West','Hayes','Rivers','Love','Young','Vale','Hart','Rhodes'];
const genres=['R&B','Soul','New Jack Swing','Hip-Hop','Rap','Funk','Disco','Pop','Neo-Soul','Contemporary R&B','Alternative R&B','Gospel','Rock','Jazz'];
const names=['Midnight Radio','Velvet Season','No Apologies','Side A','Afterglow','City of Gold','Slow Burn','Run It Back','Good Company','Open Doors','Blue Hour','All This Time','Sweet Talk','New Money','Homecoming','Summer Never Ends'];
let saves=loadSaves(),activeId=null,state=null,page='dashboard',modal=null,toastTimer;
function loadSaves(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch{return{}}}function save(){if(state&&activeId){saves[activeId]=state;localStorage.setItem(KEY,JSON.stringify(saves))}}function notify(t){const root=$('#toast-root');if(root){root.innerHTML=`<div class="toast">${esc(t)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>root.innerHTML='',2600)}}
function makeArtist(year){let f=pick(firsts),l=pick(lasts),genre=pick(era(year).genres),age=18+Math.floor(Math.random()*24);return{id:id(),name:`${f} ${l}`,stage:`${f} ${l}`,age,genre,personality:pick(['ambitious','enigmatic','generous','restless','perfectionist','charismatic']),pop:8+Math.random()*38,heat:5+Math.random()*25,active:true,real:false,relations:{},releases:[],retired:false}}
function worldArtists(year){let list=famous.filter(a=>year>=a[2]&&year<=a[3]).map(a=>({id:'real-'+a[0].replace(/\W/g,''),name:a[0],stage:a[0],age:Math.max(18,year-a[2]),genre:a[1],personality:'iconic',pop:35+Math.random()*60,heat:25+Math.random()*60,active:true,real:true,relations:{},releases:[],retired:false}));while(list.length<30)list.push(makeArtist(year));return list}
function makeTrack(artist,title,genre,pop,kind='Single',releaseYear=0){return{id:id(),artistId:artist.id,artist:artist.stage||artist.name,title,genre,pop,score:Math.max(1,pop*1.3),streams:0,sales:0,kind,year:releaseYear,weeks:0,player:false}}
function createCareer(d,slot){let year=+d.year||1978;let c={id:slot,character:{first:d.first,last:d.last,stage:d.stage||`${d.first} ${d.last}`,birth:d.birth||`${year-18}-06-15`,location:d.location||'Detroit, Michigan',avatar:d.avatar||'🎙️',style:'Vintage Soul',tattoos:[],jewelry:[],wardrobe:['Everyday Look'],outfits:[]},year,week:1,ep:100,cash:25000,heat:4,popularity:2,careerStatus:'Independent artist',releases:[],tracks:[],artists:worldArtists(year),relationships:{},groups:[],label:null,contracts:[],garage:[],properties:[],investments:0,totalStreams:0,totalSales:0,royalties:0,awards:[],achievements:[],news:[],activities:[],chart:{hot:[],albums:[]},stats:{shows:0,collaborations:0,weeks:0,numberOnes:0},settings:{},lastReport:null};
